394   * Converts a DER encoded object identifier to its textual form. This
   395   * function expects the DER object identifier without the tag.
   396   *
   397   * Returns: %ASN1_SUCCESS on success, or an error.
   398   **/
   399  int
   400  asn1_get_object_id_der (const unsigned char *der, int der_len, int *ret_len,
   401                          char *str, int str_size)
   402  {
   403    int len_len, len, k;
   404    int leading;
   405    char temp[LTOSTR_MAX_SIZE];
   406    uint64_t val, val1;
   407
   408    *ret_len = 0;
   409    if (str && str_size > 0)
   410      str[0] = 0;                 /* no oid */
   411
   412    if (str == NULL || der_len <= 0)
   413      return ASN1_GENERIC_ERROR;
   414
   415    len = asn1_get_length_der (der, der_len, &len_len);
   416
   417    if (len <= 0 || len + len_len > der_len)
   418      return ASN1_DER_ERROR;
   419
   420    val1 = der[len_len] / 40;
   421    val = der[len_len] - val1 * 40;
   422
   423    _asn1_str_cpy (str, str_size, _asn1_ltostr (val1, temp));
   424    _asn1_str_cat (str, str_size, ".");
   425    _asn1_str_cat (str, str_size, _asn1_ltostr (val, temp));
   426
   427    val = 0;
   428    leading = 1;
   429    for (k = 1; k < len; k++)
   430      {
   431        /* X.690 mandates that the leading byte must never be 0x80
   432         */
   433        if (leading != 0 && der[len_len + k] == 0x80)
   434          return ASN1_DER_ERROR;
   435        leading = 0;
   436
   437        /* check for wrap around */
   438        if (INT_LEFT_SHIFT_OVERFLOW (val, 7))
   439          return ASN1_DER_ERROR;
   440
   441        val = val << 7;
   442        val |= der[len_len + k] & 0x7F;
   443
   444        if (!(der[len_len + k] & 0x80))
   445          {
   446            _asn1_str_cat (str, str_size, ".");
   447            _asn1_str_cat (str, str_size, _asn1_ltostr (val, temp));
   448            val = 0;
   449            leading = 1;
   450          }
   451      }
   452
   453    if (INT_ADD_OVERFLOW (len, len_len))
   454      return ASN1_DER_ERROR;
   455
   456    *ret_len = len + len_len;
   457
   458    return ASN1_SUCCESS;
   459  }
